def merge_intervals(intervals):
    if not intervals:
        return []

    # sorted() creates a new list, ensuring the original input is not mutated
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = []

    for interval in sorted_intervals:
        # If the list of merged intervals is empty or the current 
        # interval does not overlap/touch the last merged interval
        if not merged or interval[0] > merged[-1][1]:
            merged.append(list(interval))
        else:
            # There is an overlap or they touch; update the end of the last interval
            merged[-1][1] = max(merged[-1][1], interval[1])

    return merged

import heapq

def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for u, v in edges:
        if v not in adj[u]:
            adj[u].add(v)
            in_degree[v] += 1

    queue = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    if not items:
        return []

    batches = []
    current_batch = []
    current_sum = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("weight must be positive and <= limit")

        if current_sum + weight <= limit:
            current_batch.append(name)
            current_sum += weight
        else:
            batches.append(current_batch)
            current_batch = [name]
            current_sum = weight

    if current_batch:
        batches.append(current_batch)

    return batches

def parse_sse(chunks):
    text = b"".join(chunks).decode('utf-8')
    lines = text.split('\n')
    results = []
    current_data = []

    for line in lines:
        stripped_line = line.rstrip('\r')
        if not stripped_line:
            if current_data:
                event_str = '\n'.join(current_data)
                if event_str == '[DONE]':
                    break
                results.append(event_str)
                current_data = []
        elif stripped_line.startswith('data:'):
            val = stripped_line[5:]
            if val.startswith(' '):
                val = val[1:]
            current_data.append(val)

    return results
